/** Runs `docker <args>` and returns stdout; throws when docker exits non-zero. */
export type DockerRun = (args: string[]) => string;
/** What one Flisk project left in Docker. */
export interface ProjectArtifacts {
    containers: string[];
    volumes: string[];
    networks: string[];
    /** `repository:tag` references: the project's golden layer tags and its service images. */
    images: string[];
}
export interface PurgeResult {
    removed: ProjectArtifacts;
    /** Objects Docker refused to remove, usually because another container still uses them. */
    kept: {
        kind: keyof ProjectArtifacts;
        name: string;
        reason: string;
    }[];
}
/**
 * The name in `names` that owns `candidate` when Flisk joins the name and a suffix with `separator`, or undefined. The
 * longest match wins, so project `shop` with a stack `admin` does not claim `shop_admin_web` while `shop-admin` is known.
 */
export declare function ownerOf(candidate: string, separator: "-" | "_", names: readonly string[], transform?: (name: string) => string): string | undefined;
export interface ProjectIdentity {
    /** The project's stacks. A Compose project or service image of a stack not named here is never claimed. */
    stacks: readonly string[];
    /** The other recorded project names on this machine; they settle a service-image prefix tie (see {@link ownerOf}). */
    knownNames?: readonly string[];
}
/**
 * Lists the Docker objects of project `name`, by the exact names the engine gives them: Compose projects
 * `<name>-<infra>` and `<name>-<stack>-autogenerated` (containers and volumes), networks `<name_underscored>_<suffix>`,
 * golden images `<name>-<layer>`, the infra image `<name>-traefik-wake-gateway` and service images `<name_underscored>_<stack>_<service>`. A name prefix is not enough:
 * project `shop` must not claim the database of `shop-admin`, which may never have been recorded. A volume without a
 * Compose project label is never claimed.
 */
export declare function listProjectArtifacts(name: string, identity: ProjectIdentity, docker?: DockerRun): ProjectArtifacts;
/**
 * Removes what {@link listProjectArtifacts} found: containers first (they hold the volumes and networks), then
 * volumes, networks and images. Images are untagged without `--force`, so an image another container runs stays.
 */
export declare function removeProjectArtifacts(artifacts: ProjectArtifacts, docker?: DockerRun): PurgeResult;
export declare function countArtifacts(artifacts: ProjectArtifacts): number;
